function weaponName(id,actor=save.char){return id==='buster'?(actor==='zero'?'Z-BUSTER / Z-SABER':'X-BUSTER'):WEAPONS[id]?.[actor]||'X-BUSTER';}
function ensureUnlocks(){save.unlocked=save.unlocked||{x:[],zero:[]};save.equipped=save.equipped||{x:'buster',zero:'buster'};for(const actor of ['x','zero']){save.unlocked[actor]=[...new Set([...(save.unlocked[actor]||[]),...save.cleared.filter(id=>WEAPONS[id])])].filter(id=>WEAPONS[id]);if(save.equipped[actor]!=='buster'&&!save.unlocked[actor].includes(save.equipped[actor]))save.equipped[actor]='buster';}}
function unlockBossReward(id){if(!WEAPONS[id])return null;ensureUnlocks();for(const actor of ['x','zero']){save.unlocked[actor]=[...new Set([...save.unlocked[actor],id])];save.equipped[actor]=id;}selected=id;return WEAPONS[id];}
function equipWeapon(id){ensureUnlocks();if(id!=='buster'&&!save.unlocked[save.char].includes(id))return false;selected=id;save.equipped[save.char]=id;persist();return true;}
function showArsenal(){const back=mode==='play'?'play':mode==='pause'?'pause':'map';mode='arsenal';resetInput();ensureUnlocks();const actor=save.char;selected=save.equipped[actor]||'buster';const entries=['buster',...save.unlocked[actor]];dialog('WEAPON ARCHIVE / '+(actor==='zero'?'ZERO':'X'),'KHO VŨ KHÍ',`<p>${actor==='zero'?'Chọn kỹ năng rồi nhấn KIẾM / KỸ NĂNG để thi triển. BẮN luôn dùng Z-Buster.':'Chọn vũ khí rồi nhấn hoặc giữ BẮN để tích lực.'}</p><p>Đang trang bị: <b>${weaponName(selected)}</b></p><div class="weaponList">${Object.entries(WEAPONS).map(([id,w])=>`<div><b>${save.unlocked[actor].includes(id)?'✓':'🔒'} ${w[actor]}</b><small>${w.boss} · ${actor==='zero'?w.zInfo:w.xInfo}</small></div>`).join('')}</div>`,[...entries.map(id=>[(selected===id?'✓ ':'')+weaponName(id),()=>{equipWeapon(id);mode=back;screen(back==='play'?null:back==='pause'?'pauseMenu':'map');if(p)updateHUD();toast('Đã trang bị '+weaponName(id),2);},id===selected]),['ĐÓNG',()=>{mode=back;screen(back==='play'?null:back==='pause'?'pauseMenu':'map');}]]);}
function activateDarkHold(){world.timeStop=3;world.darkPulse=.65;toast('DARK HOLD · Dừng thời gian 3 giây',2);beep(720,.4,'triangle',.06,100);particle(p.x+14,p.y+20,'#b7a2ff',30,220);}
function useTechnique(power=1){if(save.char!=='zero'||selected==='buster'||!WEAPONS[selected]||p.tech?.ttl>0)return false;ensureUnlocks();if(!save.unlocked.zero.includes(selected))return false;const cost=['nature','shadow','volt'].includes(selected)?22:12;if(p.energy<cost){toast('Chưa đủ năng lượng cho '+weaponName(selected),1.5);return true;}p.energy-=cost;const id=selected;p.tech={id,ttl:id==='ice'?1.1:.45,duration:id==='ice'?1.1:.45,hit:new Set(),elapsed:0};saberTimer=0;beep(220,.2,'sawtooth',.045,900);
 if(id==='shadow'){activateDarkHold();p.tech=null;}
 if(id==='nature'){p.cloneTime=7;p.tech=null;toast('TWIN DREAM · Phân thân 7 giây',2);}
 if(id==='water'){p.vy=-520;p.ground=false;}
 if(id==='ice'){p.vy=-760;p.ground=false;for(let i=0;i<3;i++)nativeProjectile('ice',p.x-22+i*25,p.y-100,(i-1)*30,260,6,'fx-icicle',22,40,2,false);}
 if(id==='wind'){p.vx=p.dir*520;wallLock=.4;}
 if(id==='metal'||id==='fire'){if(p.ground){p.vy=-440;p.ground=false;}p.tech.slam=true;}
 if(id==='volt'){for(let i=0;i<12;i++){const a=i*Math.PI/6;nativeProjectile('volt',p.x+14,p.y+20,Math.cos(a)*310,Math.sin(a)*310,8,'fx-cflasher',26,26,1.8,true);}for(const e of [...world.enemies,...(bossActive?[world.boss]:[])])if(!e.dead&&Math.abs(e.x-p.x)<520)hitEnemy(e,14,'volt');shake=8;world.darkPulse=.25;}
 return true;}
function nativeProjectile(elem,x,y,vx,vy,damage,sprite,w,h,life=2,pierce=false,power=0){const b={elem,x,y,vx,vy,damage,sprite,w,h,life,enemy:false,pierce,hit:new Set(),power,col:STAGES.find(s=>s.id===elem)?.color||'#a4f1ff',age:0};world.bullets.push(b);return b;}
function updateTechnique(dt){if(!p.tech){p.cloneTime=Math.max(0,(p.cloneTime||0)-dt);return;}const t=p.tech;t.ttl-=dt;t.elapsed+=dt;const id=t.id;if(id==='wind'){p.vx=p.dir*520;wallLock=.04;}
 if(t.slam&&t.elapsed>.12){p.vy=620;const rect={x:p.x-28,y:p.y-5,w:85,h:100};for(const e of [...world.enemies,...(bossActive?[world.boss]:[])])if(!e.dead&&!t.hit.has(e)&&overlap(rect,e)){t.hit.add(e);hitEnemy(e,14,id);}if(p.ground&&t.elapsed>.15){for(const vx of [-200,0,200]){const b=nativeProjectile(id,p.x+14,p.y+30,vx,0,9,id==='fire'?'fx-quake':'fx-metal',32,60,1.2,true);b.zone=id==='fire';}particle(p.x+14,p.y+48,stage.color,28,200);shake=6;t.ttl=0;}}
 if(id==='ice'&&t.elapsed>.15){const ceiling=world.platforms.find(pl=>p.x+p.w>pl.x&&p.x<pl.x+pl.w&&pl.y+pl.h<p.y+20&&p.y-(pl.y+pl.h)<35);if(ceiling){p.y=ceiling.y+ceiling.h+2;p.vy=0;t.hang=true;}if(t.hang){p.vy=0;if(Math.floor(t.elapsed*12)!==t.iceAt){t.iceAt=Math.floor(t.elapsed*12);nativeProjectile('ice',p.x+14,p.y+35,0,360,6,'fx-icicle',18,38,2);}}}
 if(['wind','water'].includes(id)){const rect={x:p.x-35,y:p.y-70,w:115,h:145};for(const e of [...world.enemies,...(bossActive?[world.boss]:[])])if(!e.dead&&!t.hit.has(e)&&overlap(rect,e)){t.hit.add(e);hitEnemy(e,14,id);}}
 if(t.ttl<=0)p.tech=null;}

for(const s of STAGES){if(WEAPONS[s.id])s.weapon=WEAPONS[s.id].x+' / '+WEAPONS[s.id].zero;}
ensureUnlocks();
let persist=()=>{try{localStorage.setItem('megaman-xs-v1',JSON.stringify(save))}catch{toast('Trình duyệt chưa cho lưu tiến độ. Phiên chơi vẫn tiếp tục.')}};
const A={},meta={};let mode='home',stage=STAGES[0],world=null,p=null,camera={x:0,y:0},time=0,acc=0,last=0,shake=0,transition=0,score=0,checkpoint=0,lives=3,selected='buster',toastTime=0,bossActive=false,ended=false,damageFlash=0;
let audio=null,audioOn=false,musicClock=0,musicIndex=0;const held=new Set(),sources=new Map(),pressed=new Set();let fireHold=0,fireWas=false,shotTimer=0,saberTimer=0,dashTimer=0,dashCooldown=0,wallLock=0,coyote=0,jumpBuffer=0,slashId=0,saberDuration=.34;
function beep(freq=440,dur=.08,type='square',gain=.03,end=null){if(!audioOn||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);if(end)o.frequency.exponentialRampToValueAtTime(end,audio.currentTime+dur);g.gain.setValueAtTime(gain,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}
function initAudio(){if(!audio)try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}if(audio?.state==='suspended')audio.resume();}
function music(dt){if(!audioOn||mode!=='play')return;musicClock-=dt;if(musicClock<=0){musicClock=.19;const seq=bossActive?[0,7,3,10,0,12,7,3]:[0,7,12,7,3,10,14,10,5,12,17,12,3,10,15,10];const root=stage.theme==='shadow'?110:146.83;beep(root*Math.pow(2,seq[musicIndex%seq.length]/12),.13,'triangle',.025);if(musicIndex%4===0)beep(root/2,.18,'sawtooth',.016);musicIndex++;}}
const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));const rand=(a,b)=>a+Math.random()*(b-a);
function toast(t,d=3){$('toast').textContent=t;$('toast').classList.add('show');toastTime=d;}
function key(k,down,source){if(down){if(!sources.has(source)){sources.set(source,k);if(!held.has(k))pressed.add(k);held.add(k)}}else{const old=sources.get(source);sources.delete(source);if(old&&![...sources.values()].includes(old))held.delete(old)}}
function resetInput(){held.clear();sources.clear();pressed.clear();fireHold=0;fireWas=false;document.querySelectorAll('.held').forEach(e=>e.classList.remove('held'));}
const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'jump',KeyW:'jump',ArrowUp:'jump',KeyZ:'fire',KeyJ:'fire',KeyX:'saber',KeyK:'saber',KeyC:'dash',ShiftLeft:'dash',ShiftRight:'dash'};
window.addEventListener('keydown',e=>{if(e.code==='Escape'||e.code==='KeyP'){if(!e.repeat)togglePause();e.preventDefault();return}if(e.code==='KeyQ'&&!e.repeat&&mode==='play'){cycleWeapon();e.preventDefault();return}const k=keyMap[e.code];if(k&&mode==='play'){e.preventDefault();key(k,true,e.code)}});
window.addEventListener('keyup',e=>{if(keyMap[e.code]){e.preventDefault();key(keyMap[e.code],false,e.code)}});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();initAudio();if(mode!=='play')return;try{b.setPointerCapture(e.pointerId)}catch{}key(b.dataset.key,true,e.pointerId);b.classList.add('held')});const up=e=>{key(b.dataset.key,false,e.pointerId);if(![...sources.values()].includes(b.dataset.key))b.classList.remove('held')};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
window.addEventListener('blur',()=>{if(mode==='play')pauseGame();resetInput()});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(mode==='play')pauseGame();resetInput();audio?.suspend()}else if(audioOn)initAudio()});window.addEventListener('contextmenu',e=>{if(mode==='play')e.preventDefault()});
function screen(id){if(id){$('toast').classList.remove('show');toastTime=0;}['home','map','dialog','pauseMenu'].forEach(x=>$(x).hidden=x!==id);$('hud').hidden=mode!=='play'&&mode!=='pause';$('controls').hidden=mode!=='play';$('bossHud').hidden=!bossActive||mode!=='play';document.body.classList.toggle('playing',mode==='play'||mode==='pause');}
let afterDialog=null;
function dialog(tag,title,body,buttons){$('dialogTag').textContent=tag;$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialogButtons').replaceChildren();buttons.forEach(([s,fn,primary])=>{const b=document.createElement('button');b.textContent=s;b.className=primary?'primary':'secondary';b.onclick=fn;$('dialogButtons').append(b)});screen('dialog');}
function showStory(){const old=mode;mode='info';resetInput();dialog('DATABASE / ELEMENTAL RIFT','SAU NGÀY EURASIA RƠI…',`<p><b>Bối cảnh gốc:</b> X5 xoay quanh cuộc khủng hoảng thuộc địa Eurasia. X6 tiếp nối hậu quả, với Gate và hiện tượng Nightmare.</p><p><b>Cốt truyện mới của XS:</b> Mạng SERAPH được dựng lên để tái tạo khí hậu. Khi học từ tàn dư Nightmare, nó kết luận rằng ý chí tự do là nguyên nhân của chiến tranh. SERAPH chiếm tám trạm nguyên tố, dùng bản sao ký ức Zero để khởi động “tái thiết”.</p><p>X và Zero đi từ vành đai va chạm, qua tám trạm khí hậu, rồi tới tháp trung tâm. Mỗi boss là một vệ binh bị SERAPH điều khiển. Giải phóng trạm đem lại vũ khí mới và thay đổi một vùng lân cận.</p><p><b>Fan game độc lập:</b> dùng sprite từ hai gói X5/X6 bạn cung cấp; bản đồ, thoại, mã game, âm thanh tổng hợp và cốt truyện XS được viết mới. Các chuỗi chuyển động dùng clip riêng cho từng trạng thái.</p>`,[['ĐIỀU KHIỂN',()=>showGuide(old)],['ĐÓNG',()=>{mode=old;screen(old==='pause'?'pauseMenu':old==='map'?'map':'home')},true]]);}
function showGuide(back='pause'){mode='info';resetInput();dialog('CONTROLS / TOUCH + KEYBOARD','HUNTER MANUAL',`<table><tr><td>◀ ▶ / A D</td><td>Di chuyển. Băng có quán tính.</td></tr><tr><td>NHẢY / Space</td><td>Nhảy; giữ hướng vào vách rồi nhảy để wall kick. Có đệm nhảy và coyote time.</td></tr><tr><td>DASH / C, Shift</td><td>Lướt trên đất hoặc một lần trên không. Tiếp đất nạp lại air dash.</td></tr><tr><td>BẮN / Z, J</td><td>Giữ để tích lực, thả để bắn. Đầy lực sau 1,1 giây.</td></tr><tr><td>KIẾM / X, K</td><td>Chém gần, phá đạn. Ba nhát liên tiếp tăng sát thương.</td></tr><tr><td>ĐỔI HỆ / Q</td><td>Buster luôn có; vũ khí nguyên tố mở sau khi hạ boss, dùng năng lượng tự hồi.</td></tr><tr><td>Ⅱ / P, Esc</td><td>Tạm dừng. Tự dừng khi chuyển tab.</td></tr></table><p>Chạm đồng thời nhiều nút để vừa chạy vừa nhảy và tích lực. Cột sáng xanh là checkpoint. Tìm lõi hồng trên nhánh cao để tăng máu tối đa; cứu Reploid để hồi máu. Rơi vực hoặc trúng gai mất máu, hồi về checkpoint nếu HP cạn. Có 3 mạng mỗi lần vào màn.</p><p>Với Zero, chọn kỹ năng trong KHO VŨ KHÍ rồi nhấn KIẾM / KỸ NĂNG để thi triển; BẮN luôn là Z-Buster. Hạ boss mở kỹ năng cho cả hai Hunter, tự trang bị và lưu qua các màn.</p><p>Mỗi boss có tín hiệu cảnh báo, chu kỳ tấn công và giai đoạn mạnh hơn dưới 50% HP. Vũ khí khắc hệ gây sát thương ×1,65.</p>`,[['ĐÃ HIỂU',()=>{mode=back;screen(back==='pause'?'pauseMenu':back==='map'?'map':'home')},true]]);}
function home(){mode='home';resetInput();screen('home');$('bossHud').hidden=true;}
function map(){mode='map';resetInput();screen('map');$('mapCount').textContent=save.cleared.filter(x=>x!=='intro'&&x!=='core').length+' / 8 LÕI';$('charBtn').textContent='HUNTER: '+(save.char==='zero'?'ZERO':'X');$('finalStage').disabled=STAGES.slice(1,9).some(s=>!save.cleared.includes(s.id));$('finalStage').innerHTML='09 / THÁP SERAPH <span>'+($('finalStage').disabled?'KHÓA':'SẴN SÀNG')+'</span>';const grid=$('stageGrid');grid.replaceChildren();STAGES.slice(1,9).forEach((s,i)=>{const b=document.createElement('button');b.className='stageCard';b.style.setProperty('--accent',s.color);b.style.setProperty('--tint',s.color+'30');b.innerHTML=`${save.cleared.includes(s.id)?'<span class="cleared">✓ ĐÃ GIẢI PHÓNG</span>':''}<div class="art"><span class="coord">0${i+1} / ${s.element}</span><span class="element">${['♨','❄','◉','✳','≋','⬡','ϟ','◐'][i]}</span><canvas width="160" height="160"></canvas></div><div class="stageText"><b>${s.n}</b><small>${s.tag}</small></div>`;b.querySelector('.art').style.backgroundImage='linear-gradient(90deg,#081421c9,#08142128),url(assets/environments/bg-'+s.id+'.webp?v=3)';b.querySelector('.art').style.backgroundSize='cover';b.querySelector('.art').style.backgroundPosition='center';const c=b.querySelector('canvas'),g=c.getContext('2d');g.imageSmoothingEnabled=false;if(A[s.boss])g.drawImage(A[s.boss],0,0,160,160,0,0,160,160);b.onclick=()=>briefing(s);grid.append(b)})}
function briefing(s){stage=s;mode='brief';resetInput();dialog('MISSION / '+s.en,s.n.toUpperCase(),`<p>${s.brief}</p><p><b>Địa hình:</b> ${s.tag}<br><b>Vệ binh:</b> ${s.bossName}<br><b>Vũ khí thưởng:</b> ${s.weapon}</p><p>Hunter: <b>${save.char==='zero'?'ZERO':'X'}</b> · Mỗi lượt có 3 mạng · Tiến độ chiến dịch tự lưu.</p>`,[['VỀ BẢN ĐỒ',map],['TRIỂN KHAI',()=>startStage(s),true]]);}
function maxHP(){return 32+save.relics.length*2+(save.cleared.includes('metal')?4:0)}
function startStage(s){stage=s;world=buildWorld(s.id);camera={x:0,y:230};checkpoint=0;lives=3;score=0;ensureUnlocks();selected=save.equipped[save.char]||'buster';bossActive=false;ended=false;musicIndex=0;musicClock=0;resetPlayer();mode='play';screen(null);toast(s.id==='intro'?'ALIA: Nhảy qua cầu gãy. Giữ BẮN để tích lực.':s.tag,4);$('area').textContent=s.en;updateHUD();}
function resetPlayer(){const sp=world.checkpoints[checkpoint];p={tech:null,cloneTime:0,x:sp.x,y:sp.y-56,w:28,h:48,vx:0,vy:0,dir:1,hp:maxHP(),energy:100,ground:false,wall:0,airDash:true,inv:1.8,combo:0,comboAt:0};bossActive=false;world.bullets=[];world.particles=[];world.timeStop=0;world.darkPulse=0;world.enemies.forEach(e=>{if(!e.dead){e.x=e.startX;e.y=e.startY;e.hp=e.max;e.cool=1+Math.random();}});if(world.boss){world.boss.hp=world.boss.max;world.boss.x=world.width-250;world.boss.y=world.floor-95;world.boss.t=0;world.boss.state=0;world.boss.inv=0;}dashTimer=0;dashCooldown=0;shotTimer=0;saberTimer=0;wallLock=0;coyote=0;jumpBuffer=0;resetInput();camera.x=clamp(p.x-250,0,world.width-960);camera.y=clamp(p.y-280,0,world.height-540);$('bossHud').hidden=true;}
function pauseGame(){if(mode!=='play')return;mode='pause';resetInput();screen('pauseMenu');$('pauseInfo').textContent=stage.n+' · Checkpoint '+(checkpoint+1)+' · Mạng còn '+lives;}
function togglePause(){if(mode==='play')pauseGame();else if(mode==='pause'){mode='play';resetInput();screen(null);initAudio()}}
function cycleWeapon(){ensureUnlocks();const ws=['buster',...save.unlocked[save.char]];equipWeapon(ws[(ws.indexOf(selected)+1)%ws.length]);updateHUD();toast(weaponName(selected),1.8);beep(650,.05);}
function updateHUD(){$('hpBar').style.width=Math.max(0,p.hp/maxHP()*100)+'%';$('energyBar').style.width=p.energy+'%';$('hpText').textContent=(save.char==='zero'?'ZERO':'X')+' / '+Math.ceil(p.hp)+' HP';$('pilot').textContent=save.char==='zero'?'Z':'X';$('lives').textContent='×'+lives;const saberButton=document.querySelector('[data-key="saber"]');if(saberButton){const title=save.char==='zero'&&selected!=='buster'?'KỸ NĂNG':'KIẾM';if(saberButton.firstChild&&saberButton.firstChild.nodeType===3)saberButton.firstChild.textContent=title;}const label=weaponName(selected)+'<span>KHO VŨ KHÍ / Q: ĐỔI</span>';if($('weapon').innerHTML!==label)$('weapon').innerHTML=label;$('game').dataset.state=JSON.stringify({mode,x:Math.round(p.x),y:Math.round(p.y),hp:p.hp,ground:p.ground,inv:p.inv.toFixed(2),charge:fireHold.toFixed(2),animation:p.animName,frame:p.animFrame});$('objective').textContent=bossActive?'Hạ vệ binh · Né đòn báo trước':Math.floor(p.x/world.width*100)+'% · '+(checkpoint?'Đã kích hoạt checkpoint':'Tìm trạm tiếp sóng');if(bossActive){$('bossBar').style.width=Math.max(0,world.boss.hp/world.boss.max*100)+'%';$('bossName').textContent=stage.bossName;}}
function buildWorld(id){const W={width:5600,height:920,floor:760,platforms:[],hazards:[],enemies:[],bullets:[],particles:[],items:[],checkpoints:[],boss:null};
const g=(x,w,y=760)=>W.platforms.push({x,y,w,h:920-y,kind:'ground'}),q=(x,y,w=130,kind='ledge',move=0)=>W.platforms.push({x,y,w,h:22,kind,move,baseX:x,baseY:y});
const layouts={
intro:[[0,800,760],[930,770,720],[1820,750,760],[2710,700,700],[3560,2040,760]],
fire:[[0,650,760],[800,750,720],[1700,900,760],[2770,650,700],[3570,750,760],[4470,1130,760]],
ice:[[0,700,760],[830,750,710],[1710,650,650],[2490,800,720],[3420,850,760],[4400,1200,760]],
water:[[0,850,700],[980,1050,760],[2160,850,800],[3140,1050,720],[4320,1280,760]],
nature:[[0,700,760],[850,850,710],[1840,800,760],[2790,850,690],[3790,700,760],[4620,980,760]],
wind:[[0,550,760],[780,450,700],[1450,470,640],[2150,450,700],[2840,450,640],[3510,700,720],[4430,1170,760]],
metal:[[0,800,760],[920,800,760],[1860,700,670],[2690,950,760],[3780,650,690],[4560,1040,760]],
volt:[[0,750,760],[880,750,700],[1770,800,760],[2710,700,680],[3550,850,760],[4540,1060,760]],
shadow:[[0,650,760],[800,750,700],[1700,700,760],[2550,800,680],[3500,900,760],[4540,1060,760]],
core:[[0,700,760],[840,650,680],[1630,800,760],[2570,750,660],[3460,850,760],[4450,1150,760]]};
const arr=layouts[id];arr.forEach(a=>g(...a));
// Intermediate ledges bridge every main-route gap; optional upper routes hold collectibles.
for(let i=0;i<arr.length-1;i++){const [x,w,y]=arr[i],[nx,,ny]=arr[i+1],gap=nx-x-w;if(gap>180)q(x+w+gap/2-55,Math.min(y,ny)-45,110,id==='shadow'?'phase':'ledge',id==='wind'?35:0);if(y-ny>70)q(nx-80,y-75,120);}
arr.slice(0,-1).forEach(([x,w,y],i)=>{q(x+230,y-88,140);q(x+410,y-173,130,id==='shadow'?'phase':'ledge',id==='wind'?30:0);if(w>700)q(x+570,y-253,140);});
// Distinct vertical passage, with two ways through and a wall-kick column.
if(id==='ice'&&save.cleared.includes('fire')){q(1820,565,130);q(1940,480,130);}q(1990,515,135);q(2185,440,130);q(2375,515,140);q(2080,590,90);W.platforms.push({x:2300,y:570,w:32,h:150,kind:'wall'});
if(id==='metal'){q(3080,590,160,'lift',85);q(3270,490,150);q(3460,580,140)}
if(id==='water'){q(1250,580,170);q(2900,570,160);q(3070,480,120)}
if(id==='fire'){q(2920,530,130);q(3070,440,130);q(3230,520,150)}
if(id==='core'){q(3530,590,130);q(3690,500,130);q(3870,420,140);}
const groundAt=x=>W.platforms.filter(a=>a.kind==='ground'&&a.x<=x&&a.x+a.w>=x).sort((a,b)=>a.y-b.y)[0];
function safeX(target){const f=W.platforms.filter(a=>a.kind==='ground'&&a.w>250).reduce((a,b)=>Math.abs((b.x+100)-target)<Math.abs((a.x+100)-target)?b:a);return{x:f.x+100,y:f.y}}
W.checkpoints=[{x:95,y:arr[0][2]},safeX(1800),safeX(4300)];
arr.slice(0,-1).forEach(([x,w,y],i)=>{let hx=x+w*.62;if(hx>4600)return;const typ=id==='fire'?'vent':id==='ice'?'icefall':id==='volt'?'arc':id==='metal'?'press':id==='nature'?'spikes':id==='core'?(i%2?'arc':'vent'):null;if(typ){W.hazards.push({x:hx,y:y-15,w:typ==='press'?75:65,h:15,type:typ,phase:i*.9});q(hx-25,y-100,120)}});
for(let i=0;i<15;i++){const x=500+i*275,ground=groundAt(x);if(!ground)continue;const fly=i%3===1;W.enemies.push({x,y:ground.y-(fly?165:40),startX:x,startY:ground.y-(fly?165:40),w:fly?44:30,h:fly?36:40,hp:fly?6:8,max:fly?6:8,type:fly?'drone':'sniper',dir:-1,cool:1+Math.random(),t:i,dead:false,inv:0});}
let mg=groundAt(2950)||groundAt(2850);if(mg){const x=mg.x+mg.w*.45;W.enemies.push({x,y:mg.y-90,startX:x,startY:mg.y-90,w:68,h:84,hp:36,max:36,type:'brute',dir:-1,cool:1,t:0,dead:false,inv:0});}
W.items.push({id:id+'-relic',x:2195,y:402,w:28,h:30,type:'relic',got:save.relics.includes(id+'-relic')});
for(let i=0;i<3;i++){const x=620+i*1300,gr=groundAt(x);if(gr)W.items.push({id:id+'-rescue-'+i,x,y:gr.y-40,w:25,h:40,type:'rescue',variant:(i+STAGES.findIndex(s=>s.id===id))%6,got:save.rescues.includes(id+'-rescue-'+i)});}
W.items.push({id:id+'-heal',x:W.checkpoints[2].x+80,y:W.checkpoints[2].y-35,w:23,h:23,type:'heal',got:false});
W.boss={x:5350,y:760-95,w:76,h:95,hp:id==='core'?240:id==='intro'?80:150,max:id==='core'?240:id==='intro'?80:150,dir:-1,t:0,action:0,state:0,inv:0,attackAt:1.2,charging:false,vx:0};return W;}
function particle(x,y,col,n=12,speed=120){for(let i=0;i<n;i++){if(world.particles.length>240)break;world.particles.push({x,y,vx:rand(-speed,speed),vy:rand(-speed,speed),life:rand(.2,.65),max:.65,col,size:rand(2,5)})}}
function hurt(d=4,knock=0){if(p.inv>0||ended)return;p.hp-=d;p.inv=1.2;p.vy=-250;p.vx=knock||-p.dir*160;wallLock=.14;shake=7;damageFlash=.16;beep(140,.18,'sawtooth',.07,55);particle(p.x+p.w/2,p.y+20,'#91eaff',13);if(p.hp<=0)die();}
function die(){if(ended)return;ended=true;lives--;p.hp=0;transition=.9;particle(p.x+14,p.y+22,'#82e9ff',45,260);beep(550,.5,'triangle',.09,70);}
function finish(){if(ended)return;ended=true;resetInput();save.cleared=[...new Set([...save.cleared,stage.id])];unlockBossReward(stage.id);if(stage.theme==='intro')save.intro=true;persist();transition=2.0;particle(world.boss.x+40,world.boss.y+40,stage.color,100,340);shake=15;beep(220,.5,'triangle',.1,880);}
function result(){mode='result';$('bossHud').hidden=true;const all=stage.theme==='core';dialog(all?'MISSION COMPLETE / A NEW DAWN':'CORE RESTORED / '+stage.element,all?'BÌNH MINH MỚI':'TRẠM ĐÃ GIẢI PHÓNG',`<p>${stage.end}</p>${WEAPONS[stage.id]?`<div class="rewardCards"><div><small>X / VŨ KHÍ ĐÃ HỌC</small><b>${WEAPONS[stage.id].x}</b><p>${WEAPONS[stage.id].xInfo}</p></div><div><small>ZERO / KỸ NĂNG ĐÃ HỌC</small><b>${WEAPONS[stage.id].zero}</b><p>${WEAPONS[stage.id].zInfo}</p></div></div><p>Đã tự trang bị cho cả X và Zero. Vũ khí được giữ khi sang màn khác.</p>`:`<p><b>${stage.weapon}</b> · ${stage.theme==='intro'?'Mở bản đồ tám vùng':'Chiến dịch hoàn tất'}</p>`}<p>Điểm chiến đấu: <b>${score}</b> · Mạng còn: <b>${lives}</b><br>Lõi tăng HP: <b>${save.relics.length}/10</b> · Reploid đã cứu: <b>${save.rescues.length}</b></p>`,[['BẢN ĐỒ CHIẾN DỊCH',map,true],['CHƠI LẠI',()=>startStage(stage)]]);}
function shoot(power){if(ended||shotTimer>0)return;const zero=save.char==='zero';let elem=zero?'buster':selected;const cost=elem==='buster'?0:power>=2?18:8;if(elem!=='buster'&&p.energy<cost){elem='buster';toast('Năng lượng thấp · Chuyển tạm sang Buster',1.3)}else p.energy-=cost;if(elem==='shadow'){activateDarkHold();shotTimer=.35;return;}
const x=p.x+14+p.dir*22,y=p.y+20;const damage=power>=2?10:power?5:2;let b;
if(elem==='buster'){b=nativeProjectile('buster',x,y,p.dir*720,0,damage,zero?'fx-zbuster':power>=2?'fx-charge':'fx-buster',power>=2?42:power?24:13,power>=2?26:power?16:8,2,power>=2,power);}
else if(elem==='fire'){b=nativeProjectile(elem,x,y,p.dir*330,-70,damage*1.3,'fx-fire',24,32,2.5,true,power);b.gravity=true;b.explosive=true;}
else if(elem==='ice'){b=nativeProjectile(elem,x,y,p.dir*410,-80,damage*1.25,'fx-ice',28,28,2.3,false,power);b.gravity=true;if(power>=2){for(const v of [-140,140])nativeProjectile(elem,x,y,p.dir*410,v,7,'fx-ice',25,25,2,false,power);}}
else if(elem==='water'){for(const a of [-.9,0,.9]){b=nativeProjectile(elem,x,y,p.dir*Math.cos(a)*480,Math.sin(a)*480,damage*1.2,'fx-water',24,24,2.4,power>=2,power);}}
else if(elem==='nature'){b=nativeProjectile(elem,x,y,p.dir*300,-50,damage*2,'fx-nature',44,44,3,true,power);b.gravity=true;}
else if(elem==='wind'){b=nativeProjectile(elem,x+p.dir*25,y-20,p.dir*90,-190,damage*1.35,'fx-wind',50,65,2.3,true,power);if(power>=2){nativeProjectile(elem,x+p.dir*70,y-40,p.dir*130,-160,8,'fx-wind',60,80,2.3,true,power);}}
else if(elem==='metal'){b=nativeProjectile(elem,x,y,p.dir*360,-180,damage*1.9,'fx-metal',32,34,3,true,power);b.gravity=true;}
else if(elem==='volt'){b=nativeProjectile(elem,x,y,p.dir*(power>=2?800:360),0,damage*1.5,power>=2?'fx-laser':'fx-volt',power>=2?80:28,power>=2?32:16,2.6,power>=2,power);b.chain=power>=2;}
if(b){particle(x,y,STAGES.find(s=>s.id===elem)?.color||'#a4f1ff',5,50);shotTimer=.2;shake=power>=2?3:0;beep(power>=2?180:power?340:640,.11,'square',.035,power>=2?760:280);}}
function slash(){if(saberTimer>0||ended)return;const since=time-p.comboAt;p.combo=since<.65?(p.combo+1)%3:0;p.comboAt=time;saberDuration=save.char==='zero'?.32:.34;saberTimer=saberDuration;p.saberAir=!p.ground;slashId++;beep(450+p.combo*140,.14,'sawtooth',.04,1300);}
function hitEnemy(e,d,elem){if(e.inv>0||e.dead)return;const isBoss=e===world.boss;if(isBoss&&elem===stage.weak)d*=1.65;if(elem==='ice')e.slow=2;if(elem==='fire')particle(e.x+e.w/2,e.y+20,'#ff9654',20,180);e.hp-=d;e.inv=isBoss?.22:.12;particle(e.x+e.w/2,e.y+e.h/2,isBoss?stage.color:'#ffe1a5',isBoss?12:7,130);if(e.hp<=0){if(isBoss){finish();return}e.dead=true;score+=e.type==='brute'?300:100;particle(e.x+e.w/2,e.y+20,'#ffb567',22,180);beep(110,.14,'sawtooth',.045,45);if(Math.random()<.35){world.items.push({id:'drop'+time,x:e.x,y:e.y,w:18,h:18,type:'heal',got:false})}}}
function enemyShot(x,y,vx,vy,size=9,col='#ff9775',life=4){world.bullets.push({x,y,vx,vy,w:size,h:size,damage:4,life,enemy:true,col,elem:'enemy',sprite:bossActive&&stage.id!=='core'&&stage.id!=='intro'?(stage.theme==='shadow'?'fx-cflasher':'fx-'+stage.id):null,age:0,hit:new Set()});}
